// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // deposit 1 ether
        vm.deal(address(0x1234), 1 ether);
        vm.prank(address(0x1234));
        (bool ok,) = address(c).call{value: 1 ether}("");
        require(ok, "deposit failed");

        // attempt withdraw: reference succeeds, buggy version reverts due to underflow
        vm.prank(address(0x1234));
        bool withdrawOk;
        try c.withdraw() {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }
        // reference: withdraw succeeds; buggy: reverts (underflow) => withdrawOk false
        assertTrue(withdrawOk);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        (bool okDeposit, ) = address(c).call{value: 1 ether}("");
        require(okDeposit, "deposit failed");
        // Now try withdrawal — use try/catch because buggy version reverts.
        vm.prank(alice);
        bool okWithdraw;
        try c.withdraw() {
            okWithdraw = true;
        } catch {
            okWithdraw = false;
        }
        // In reference version withdrawal succeeds -> okWithdraw true.
        // In buggy version withdrawal reverts (underflow in balances) -> okWithdraw false.
        assertTrue(okWithdraw);
    }
}

