pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        (bool okFallback, ) = address(c).call{value: 1 ether}("");
        assertTrue(okFallback);
        vm.prank(user);
        (bool okWithdraw, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        assertTrue(okWithdraw);
    }
}
